{"file_path":"src/parser.js","content":"/**
 * Parsing of the election description read from standard input.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9][0-9]*$/

export class ParseError extends Error {
  constructor(message, line) {
    super(message)
    this.line = line
  }
}

function fail(message, line) {
  throw new ParseError(message, line)
}

/**
 * Parses the election text into a list of candidate names and a list of
 * ballots. Throws ParseError on any malformed line, matching the CLI's
 * error messages.
 */
export function parseElection(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) {
      continue
    }
    const tokens = trimmed.split(/\s+/)
    const word = tokens[0]

    if (word === 'candidates') {
      if (candidates !== null) {
        fail('candidates must be declared once, before any ballot', lineNo)
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        fail('expected candidates <name>...', lineNo)
      }
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          fail(`invalid candidate name ${name}`, lineNo)
        }
        if (candidateSet.has(name)) {
          fail(`candidate ${name} is declared twice`, lineNo)
        }
        candidateSet.add(name)
      }
      candidates = names
    } else if (word === 'ballot') {
      if (candidates === null) {
        fail('candidates must be declared once, before any ballot', lineNo)
      }
      if (tokens.length < 3) {
        fail('expected ballot <count> <candidate>...', lineNo)
      }
      const countStr = tokens[1]
      if (!COUNT_RE.test(countStr)) {
        fail('count must be a positive integer', lineNo)
      }
      const count = Number(countStr)
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          fail(`unknown candidate ${name}`, lineNo)
        }
        if (seen.has(name)) {
          fail(`candidate ${name} is repeated`, lineNo)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      fail(`unknown directive ${word}`, lineNo)
    }
  }

  if (candidates === null) {
    fail('no candidates', undefined)
  }

  return { candidates, ballots }
}
"}

