{"file_path":"src/election.js","content":"/**
 * The instant-runoff count itself, independent of how it is reported.
 */

/**
 * Picks which of the tied-for-fewest candidates is eliminated.
 *
 * Compares the tied candidates round by round from the first round counted
 * onwards (this round included). At the first round where their counts
 * differ, only the candidates with the fewest votes in that round remain in
 * contention, and the comparison starts over from the first round for the
 * survivors. Since rounds before a divergence are equal for any subset, this
 * is equivalent to simply narrowing the set forward as a divergence is
 * found. When no round ever separates them, the one whose name sorts last
 * by code point is eliminated.
 */
function pickElimination(tied, history) {
  let candidates = tied
  for (let round = 0; round < history.length && candidates.length > 1; round++) {
    const tallies = history[round]
    const votes = candidates.map((name) => tallies.get(name))
    const min = Math.min(...votes)
    if (!votes.every((v) => v === min)) {
      candidates = candidates.filter((name) => tallies.get(name) === min)
    }
  }
  if (candidates.length === 1) {
    return candidates[0]
  }
  return candidates.reduce((worst, name) => (name > worst ? name : worst))
}

/**
 * Runs the full instant-runoff count.
 *
 * Returns the list of rounds counted, each holding the vote tally for every
 * still-continuing candidate, the exhausted-ballot count, the candidate
 * eliminated afterward (or null when the round ended the election), and the
 * winner's name (or null when no candidate ever reached a majority).
 */
export function runElection(candidates, ballots) {
  let continuing = new Set(candidates)
  const rounds = []
  const history = []
  let winner = null

  for (;;) {
    const tallies = new Map()
    for (const name of continuing) {
      tallies.set(name, 0)
    }
    let exhausted = 0
    for (const ballot of ballots) {
      const target = ballot.names.find((name) => continuing.has(name))
      if (target === undefined) {
        exhausted += ballot.count
      } else {
        tallies.set(target, tallies.get(target) + ballot.count)
      }
    }
    history.push(tallies)

    const activeTotal = [...tallies.values()].reduce((a, b) => a + b, 0)

    let eliminated = null
    if (activeTotal === 0) {
      winner = null
      rounds.push({ tallies, exhausted, eliminated })
      break
    }

    const majorityWinner = [...tallies.entries()].find(([, v]) => v * 2 > activeTotal)
    if (majorityWinner !== undefined) {
      winner = majorityWinner[0]
      rounds.push({ tallies, exhausted, eliminated })
      break
    }

    const min = Math.min(...tallies.values())
    const tiedForFewest = [...tallies.keys()].filter((name) => tallies.get(name) === min)
    eliminated = tiedForFewest.length === 1 ? tiedForFewest[0] : pickElimination(tiedForFewest, history)
    rounds.push({ tallies, exhausted, eliminated })
    continuing = new Set([...continuing].filter((name) => name !== eliminated))
  }

  return { rounds, winner }
}
"}

