{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */

import { readFileSync } from 'node:fs'
import { parseElection, ParseError } from './parser.js'
import { runElection } from './election.js'

function formatRound(index, round) {
  const entries = [...round.tallies.entries()].sort((a, b) => {
    if (b[1] !== a[1]) return b[1] - a[1]
    return a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0
  })
  const parts = entries.map(([name, votes]) => `${name}=${votes}`)
  parts.push(`exhausted=${round.exhausted}`)
  return `round ${index}: ${parts.join(' ')}`
}

function main() {
  const mode = process.argv[2]
  if (mode !== 'rounds' && mode !== 'tally') {
    process.stderr.write('error: usage: cli.js rounds|tally\n')
    process.exit(2)
  }

  const input = readFileSync(0, 'utf8')

  let election
  try {
    election = parseElection(input)
  } catch (err) {
    if (err instanceof ParseError) {
      const location = err.line === undefined ? '' : `line ${err.line}: `
      process.stderr.write(`error: ${location}${err.message}\n`)
      process.exit(2)
    }
    throw err
  }

  const { rounds, winner } = runElection(election.candidates, election.ballots)

  const output = []
  if (mode === 'rounds') {
    rounds.forEach((round, i) => {
      output.push(formatRound(i + 1, round))
      if (round.eliminated !== null) {
        output.push(`eliminated ${round.eliminated}`)
      }
    })
  } else {
    output.push(`rounds ${rounds.length}`)
  }
  output.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(output.join('\n') + '\n')
  process.exit(0)
}

main()
"}

